FILES = {'core/config/config.go': 'package config\n\nimport "github.com/caarlos0/env/v11"\n\n// Config holds all server settings sourced from environment variables.\ntype Config struct {\n\t// PostgreSQL\n\tDatabaseURL string `env:"MEMPALACE_DB_URL"`\n\tPoolMin     int32  `env:"MEMPALACE_PG_POOL_MIN" envDefault:"2"`\n\tPoolMax     int32  `env:"MEMPALACE_PG_POOL_MAX" envDefault:"10"`\n\n\t// Multi-tenancy\n\tTenantID string `env:"MEMPALACE_TENANT_ID" envDefault:"default"`\n\n\t// Auth\n\tMCPAPIKey         string `env:"MCP_API_KEY"`          // full access (read + write); required\n\tMCPAPIKeyReadOnly string `env:"MCP_API_KEY_READONLY"` // optional read-only key; "" disables it\n\n\t// Embedding (OpenAI-compatible API — works with Ollama, LM Studio, etc.)\n\tEmbedAPIURL string `env:"EMBED_API_URL" envDefault:"http://localhost:11434/v1"` // e.g. http://ollama:11434/v1\n\tEmbedAPIKey string `env:"EMBED_API_KEY"`                                        // optional, e.g. for OpenAI\n\tEmbedModel  string `env:"EMBED_MODEL" envDefault:"embeddinggemma"`              // e.g. embeddinggemma (multilingual, 100+ langs), nomic-embed-text, text-embedding-3-small\n\tEmbedDim    int    `env:"EMBED_DIM" envDefault:"768"`                           // must equal model output, cannot exceed it; 768 for embeddinggemma (Matryoshka: also 512/256/128)\n\n\t// HNSW search quality (higher = better recall, slower)\n\tEFSearch int `env:"MEMPALACE_HNSW_EF_SEARCH" envDefault:"100"`\n\n\t// Optional plain REST/JSON API (off by default; MCP is always on)\n\tEnableRESTAPI bool `env:"ENABLE_REST_API" envDefault:"false"`\n\n\t// Room redirects (opt-in). When enabled, the redirect tools are exposed and\n\t// add_drawer / search / list_drawers transparently follow a merged/renamed\n\t// room to its canonical target. Default off — no redirect tools are\n\t// registered and add_drawer stays storage-only, preserving existing behavior.\n\tRoomRedirects bool `env:"MEMPALACE_ROOM_REDIRECTS" envDefault:"false"`\n\n\t// Dream consolidation job (cmd/dreamjob). Scans rooms once per run and writes\n\t// near-duplicate merge candidates for review — it never merges anything\n\t// itself. Consumed by the mempalace_*_merge_candidate MCP tools.\n\tDreamSemantic  bool    `env:"MEMPALACE_DREAM_SEMANTIC" envDefault:"true"`  // also cluster by embedding similarity, not just name normalization\n\tDreamThreshold float64 `env:"MEMPALACE_DREAM_THRESHOLD" envDefault:"0.88"` // cosine cutoff for the semantic tier (0..1)\n\n\t// Apache AGE entity graph (opt-in). Managed PostgreSQL services commonly\n\t// disallow LOAD \'age\', so AGE is disabled unless explicitly enabled. The\n\t// plain-SQL temporal knowledge graph remains available either way.\n\tAGEEnabled bool `env:"MEMPALACE_AGE_ENABLED" envDefault:"false"`\n\n\t// Knowledge-graph auto-population (opt-in). When enabled, add_drawer also\n\t// writes to the AGE graph using the selected extractor strategy. This is\n\t// automatically disabled at startup when AGEEnabled is false.\n\tGraphAutoPopulate bool   `env:"MEMPALACE_GRAPH_AUTO_POPULATE" envDefault:"false"`\n\tGraphExtractor    string `env:"MEMPALACE_GRAPH_EXTRACTOR" envDefault:"structural"` // "structural" (deterministic, no LLM) or "llm"\n\n\t// LLM extraction — only used when GraphExtractor == "llm".\n\t//\n\t// LLMProvider selects how the chat endpoint is called:\n\t//   "openai" (default) — OpenAI-compatible /v1/chat/completions. Works with\n\t//       OpenAI, LM Studio, LocalAI, and Ollama\'s compat layer. NOTE: you must\n\t//       use a NON-thinking model here — a reasoning model streams a long\n\t//       <think> block that this endpoint cannot suppress, blowing the timeout.\n\t//       Set LLM_API_URL to the base incl. /v1 (e.g. http://host:11434/v1).\n\t//   "ollama" — Ollama-native /api/chat with think=false, which disables\n\t//       reasoning, so thinking models (qwen3, …) work. Set LLM_API_URL to the\n\t//       Ollama root WITHOUT /v1 (e.g. http://host:11434).\n\tLLMProvider string `env:"LLM_PROVIDER" envDefault:"openai"` // "openai" | "ollama"\n\tLLMAPIURL   string `env:"LLM_API_URL"`                      // openai: http://host:11434/v1 · ollama: http://host:11434\n\tLLMAPIKey   string `env:"LLM_API_KEY"`                      // optional (empty for local servers)\n\tLLMModel    string `env:"LLM_MODEL"`                        // e.g. llama3.2 (openai), qwen3 (ollama)\n\n\t// HTTP\n\tPort string `env:"PORT" envDefault:"8000"`\n}\n\n// Load reads the configuration from the process environment. It returns an\n// error if any variable cannot be parsed into its target type.\nfunc Load() (Config, error) {\n\treturn env.ParseAs[Config]()\n}\n', 'core/storage/pool.go': 'package storage\n\nimport (\n\t"context"\n\t"fmt"\n\t"log"\n\t"regexp"\n\t"strings"\n\n\t"github.com/jackc/pgx/v5"\n\t"github.com/jackc/pgx/v5/pgtype"\n\t"github.com/jackc/pgx/v5/pgxpool"\n\tpgxvec "github.com/pgvector/pgvector-go/pgx"\n\n\t"mempalace/core/config"\n)\n\n// NewPool creates a pgxpool with pgvector registered on every connection.\n// Apache AGE session setup runs only when MEMPALACE_AGE_ENABLED=true.\nfunc NewPool(ctx context.Context, cfg config.Config) (*pgxpool.Pool, error) {\n\tpcfg, err := pgxpool.ParseConfig(cfg.DatabaseURL)\n\tif err != nil {\n\t\treturn nil, fmt.Errorf("parse db url: %w", err)\n\t}\n\n\tpcfg.MinConns = cfg.PoolMin\n\tpcfg.MaxConns = cfg.PoolMax\n\n\t// Register pgvector for every new connection. AGE setup is opt-in because\n\t// managed PostgreSQL services may reject LOAD \'age\' for application roles.\n\tpcfg.AfterConnect = func(ctx context.Context, conn *pgx.Conn) error {\n\t\t// pgvector — required for vector columns\n\t\tif err := pgxvec.RegisterTypes(ctx, conn); err != nil {\n\t\t\treturn err\n\t\t}\n\n\t\tif !cfg.AGEEnabled {\n\t\t\treturn nil\n\t\t}\n\n\t\t// AGE: load the shared library for this session.\n\t\t// No-op when \'age\' is already in shared_preload_libraries.\n\t\t// Non-fatal: server still works without AGE-backed entity tools.\n\t\tif _, err := conn.Exec(ctx, "LOAD \'age\'"); err != nil {\n\t\t\tlog.Printf("pool: LOAD age: %v (AGE unavailable — entity-graph tools disabled)", err)\n\t\t\treturn nil\n\t\t}\n\t\t// Include ag_catalog in search_path so AGE operators (@>, etc.) and\n\t\t// the agtype type are resolved without schema prefix.\n\t\tif _, err := conn.Exec(ctx, `SET search_path = ag_catalog, "$user", public`); err != nil {\n\t\t\tlog.Printf("pool: SET search_path for AGE: %v", err)\n\t\t}\n\t\t// Register agtype as a text-decoded type so pgx can scan it into string.\n\t\tvar agtypeOID uint32\n\t\tif err := conn.QueryRow(ctx,\n\t\t\t"SELECT oid FROM pg_type WHERE typname = \'agtype\'",\n\t\t).Scan(&agtypeOID); err == nil {\n\t\t\tconn.TypeMap().RegisterType(&pgtype.Type{\n\t\t\t\tName:  "agtype",\n\t\t\t\tOID:   agtypeOID,\n\t\t\t\tCodec: pgtype.TextCodec{},\n\t\t\t})\n\t\t}\n\t\treturn nil\n\t}\n\n\tpool, err := pgxpool.NewWithConfig(ctx, pcfg)\n\tif err != nil {\n\t\treturn nil, fmt.Errorf("create pool: %w", err)\n\t}\n\n\tif err := pool.Ping(ctx); err != nil {\n\t\tpool.Close()\n\t\treturn nil, fmt.Errorf("ping database: %w", err)\n\t}\n\treturn pool, nil\n}\n\n// ---------------------------------------------------------------------------\n// Identifier helpers\n// ---------------------------------------------------------------------------\n\nvar (\n\treUnsafe     = regexp.MustCompile(`[^a-zA-Z0-9]`)\n\treMultiUnder = regexp.MustCompile(`_+`)\n)\n\n// SafeSchemaName converts an arbitrary tenant ID to a safe PostgreSQL schema\n// name of the form mp_{sanitized} (max 63 chars, only [a-z0-9_]).\nfunc SafeSchemaName(tenantID string) string {\n\ts := reUnsafe.ReplaceAllString(tenantID, "_")\n\ts = strings.ToLower(s)\n\ts = reMultiUnder.ReplaceAllString(s, "_")\n\ts = strings.Trim(s, "_")\n\tif s == "" {\n\t\ts = "default"\n\t}\n\tname := "mp_" + s\n\tif len(name) > 63 {\n\t\tname = name[:63]\n\t}\n\treturn name\n}\n\n// safeTableName converts a collection name to a valid table identifier.\nfunc safeTableName(name string) string {\n\ts := reUnsafe.ReplaceAllString(name, "_")\n\ts = strings.ToLower(s)\n\ts = reMultiUnder.ReplaceAllString(s, "_")\n\ts = strings.Trim(s, "_")\n\tif s == "" {\n\t\ts = "drawers"\n\t}\n\tif len(s) > 63 {\n\t\ts = s[:63]\n\t}\n\treturn s\n}\n', 'server/cmd/mempalace/main.go': 'package main\n\nimport (\n\t"context"\n\t"errors"\n\t"log"\n\t"net/http"\n\t"os"\n\t"os/signal"\n\t"syscall"\n\t"time"\n\n\t"mempalace/core/config"\n\t"mempalace/core/embed"\n\t"mempalace/core/storage"\n\t"mempalace/server/internal/auth"\n\t"mempalace/server/internal/handler"\n)\n\nfunc main() {\n\tcfg, err := config.Load()\n\tif err != nil {\n\t\tlog.Fatalf("failed to load configuration: %v", err)\n\t}\n\n\tif cfg.DatabaseURL == "" {\n\t\tlog.Fatal("MEMPALACE_DB_URL is required")\n\t}\n\tif cfg.MCPAPIKey == "" {\n\t\tlog.Println("WARNING: MCP_API_KEY is not set — all requests will be rejected")\n\t}\n\tif cfg.MCPAPIKeyReadOnly != "" {\n\t\tif cfg.MCPAPIKeyReadOnly == cfg.MCPAPIKey {\n\t\t\tlog.Fatal("MCP_API_KEY_READONLY must differ from MCP_API_KEY")\n\t\t}\n\t\tlog.Println("read-only API key enabled (MCP_API_KEY_READONLY)")\n\t}\n\n\tctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)\n\tdefer cancel()\n\n\t// --- Database ---\n\tpool, err := storage.NewPool(ctx, cfg)\n\tif err != nil {\n\t\tlog.Fatalf("connect to database: %v", err)\n\t}\n\tdefer pool.Close()\n\n\tif err := storage.Provision(ctx, pool, cfg.TenantID, cfg.EmbedDim); err != nil {\n\t\tlog.Fatalf("provision schema: %v", err)\n\t}\n\n\tcol := storage.NewCollection(pool, cfg.TenantID, cfg.EFSearch)\n\n\t// --- Temporal knowledge graph, tunnels, settings (plain SQL) ---\n\t// These are always available; provisioning is idempotent.\n\tif err := storage.ProvisionKG(ctx, pool, cfg.TenantID); err != nil {\n\t\tlog.Fatalf("provision knowledge graph: %v", err)\n\t}\n\tif err := storage.ProvisionTunnels(ctx, pool, cfg.TenantID); err != nil {\n\t\tlog.Fatalf("provision tunnels: %v", err)\n\t}\n\tif err := storage.ProvisionSettings(ctx, pool, cfg.TenantID); err != nil {\n\t\tlog.Fatalf("provision settings: %v", err)\n\t}\n\ttriples := storage.NewTripleStore(pool, cfg.TenantID)\n\ttunnels := storage.NewTunnelStore(pool, cfg.TenantID)\n\tsettings := storage.NewSettingsStore(pool, cfg.TenantID)\n\n\t// Room redirects are opt-in (MEMPALACE_ROOM_REDIRECTS). When off, both stores\n\t// stay nil: no redirect/merge tools are exposed and resolveRoom is a no-op.\n\t// The merge-candidate table is shared with the dreamjob microservice, which\n\t// provisions it independently.\n\tvar redirects *storage.RedirectStore\n\tvar mergeCandidates *storage.MergeCandidateStore\n\tif cfg.RoomRedirects {\n\t\tif err := storage.ProvisionRedirects(ctx, pool, cfg.TenantID); err != nil {\n\t\t\tlog.Fatalf("provision room redirects: %v", err)\n\t\t}\n\t\tif err := storage.ProvisionMergeCandidates(ctx, pool, cfg.TenantID); err != nil {\n\t\t\tlog.Fatalf("provision merge candidates: %v", err)\n\t\t}\n\t\tredirects = storage.NewRedirectStore(pool, cfg.TenantID)\n\t\tmergeCandidates = storage.NewMergeCandidateStore(pool, cfg.TenantID)\n\t\tlog.Printf("room redirects enabled")\n\t}\n\n\t// --- Entity-graph (Apache AGE) ---\n\t// AGE is opt-in. The plain-SQL temporal knowledge graph above remains\n\t// available when AGE is disabled or unavailable.\n\tvar graph *storage.Graph\n\tif cfg.AGEEnabled {\n\t\tif err := storage.ProvisionGraph(ctx, pool, cfg.TenantID); err != nil {\n\t\t\tlog.Printf("entity graph (AGE) unavailable: %v", err)\n\t\t} else {\n\t\t\tgraph = storage.NewGraph(pool, cfg.TenantID)\n\t\t}\n\t} else {\n\t\tif cfg.GraphAutoPopulate {\n\t\t\tlog.Printf("graph auto-populate disabled because MEMPALACE_AGE_ENABLED=false")\n\t\t\tcfg.GraphAutoPopulate = false\n\t\t}\n\t\tlog.Printf("entity graph (AGE) disabled; temporal triple-store KG remains available")\n\t}\n\n\t// --- Embedding client ---\n\tembedClient := embed.NewClient(cfg.EmbedAPIURL, cfg.EmbedAPIKey, cfg.EmbedModel, cfg.EmbedDim)\n\n\t// --- HTTP server ---\n\tmux := http.NewServeMux()\n\th := handler.New(col, graph, triples, tunnels, redirects, mergeCandidates, settings, embedClient, cfg)\n\th.Register(mux)\n\n\t// Optional plain REST/JSON API (off unless ENABLE_REST_API=true).\n\tif cfg.EnableRESTAPI {\n\t\th.RegisterREST(mux)\n\t\tlog.Printf("REST API enabled at /mp/api/v1")\n\t}\n\n\tsrv := &http.Server{\n\t\tAddr:         ":" + cfg.Port,\n\t\tHandler:      auth.Bearer(cfg.MCPAPIKey, cfg.MCPAPIKeyReadOnly, mux),\n\t\tReadTimeout:  30 * time.Second,\n\t\tWriteTimeout: 60 * time.Second,\n\t\tIdleTimeout:  120 * time.Second,\n\t}\n\n\t// Graceful shutdown on SIGTERM / SIGINT\n\tstop := make(chan os.Signal, 1)\n\tsignal.Notify(stop, syscall.SIGTERM, syscall.SIGINT)\n\n\tgo func() {\n\t\tlog.Printf("mempalace-go listening on :%s (tenant=%s)", cfg.Port, cfg.TenantID)\n\t\tif err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {\n\t\t\tlog.Fatalf("listen: %v", err)\n\t\t}\n\t}()\n\n\t<-stop\n\tlog.Println("shutting down…")\n\n\tshutCtx, shutCancel := context.WithTimeout(context.Background(), 15*time.Second)\n\tdefer shutCancel()\n\n\tif err := srv.Shutdown(shutCtx); err != nil {\n\t\tlog.Printf("shutdown: %v", err)\n\t}\n\tlog.Println("done")\n}\n', 'README.md': '# MemPalace Server\n\nA fast, self-hosted memory server for AI agents — written in Go.\n\nThis is the **server** for [MemPalace](https://github.com/MemPalace/mempalace).\nIt gives your AI agents a long-term memory they can search, grow, and connect\nover time. Agents talk to it over the [MCP](https://modelcontextprotocol.io)\nprotocol via simple HTTP.\n\n> Looking for the main project, docs, and clients?\n> 👉 **https://github.com/MemPalace/mempalace**\n\n---\n\n## What it does\n\nMemPalace stores memories like a real memory palace:\n\n- **Wings** → broad areas (e.g. a project)\n- **Rooms** → topics inside a wing\n- **Drawers** → the actual memories\n\nOn top of that, it builds connections between memories:\n\n- **Semantic search** — find memories by meaning, not just keywords.\n- **Knowledge graph** — facts with time (what was true, and when).\n- **Entity graph** — people, things, and how they relate.\n- **Tunnels** — links between related memories.\n- **Room hygiene** *(opt-in)* — merge/rename rooms without fragmenting the\n  taxonomy, plus a scheduled "dream" job that proposes near-duplicate merges.\n  See [ROOM_REDIRECTS.md](./ROOM_REDIRECTS.md).\n\nAgents use all of this through ready-made MCP tools (search, add, recall,\ntraverse, and more).\n\n---\n\n## Why use it\n\n- **Fast & small** — a single Go binary, low memory, quick startup.\n- **Self-hosted & private** — your data stays in your own PostgreSQL.\n- **Multilingual** — uses the `embeddinggemma` model (100+ languages out of the box).\n- **Bring your own embeddings** — works with any OpenAI-compatible API\n  (Ollama, LM Studio, LocalAI, OpenAI, …).\n- **Multi-tenant** — keep many users or projects fully separated.\n- **Production-ready** — Docker Compose for local use, Kubernetes manifests for deploy.\n- **Secure by default** — every request needs an API key.\n\n---\n\n## How it works\n\n```\n┌─────────────┐     MCP over HTTP      ┌──────────────────┐\n│  AI agent   │ ─────────────────────► │  MemPalace Server│\n│ (MCP client)│                        │      (Go)        │\n└─────────────┘                        └────────┬─────────┘\n                                                 │\n                          ┌──────────────────────┼───────────────────────┐\n                          ▼                       ▼                       ▼\n                   ┌────────────┐         ┌──────────────┐        ┌──────────────┐\n                   │ PostgreSQL │         │  Embedding   │        │ Apache AGE   │\n                   │ + pgvector │         │  API (Ollama)│        │ (entity graph)│\n                   └────────────┘         └──────────────┘        └──────────────┘\n```\n\n---\n\n## Requirements\n\n- **Docker** and **Docker Compose** (easiest path), or **Go 1.26+** to build from source.\n- An **embedding API**. The default config expects [Ollama](https://ollama.com)\n  with the `embeddinggemma` model:\n\n  ```bash\n  ollama pull embeddinggemma\n  ```\n\n---\n\n## Quick start (Docker Compose)\n\nThis is the fastest way to try it. It starts PostgreSQL (with pgvector + AGE)\nand the MemPalace server together.\n\n**1. Get the code**\n\n```bash\ngit clone https://github.com/sefodo26/mempalace-server.git\ncd mempalace-server\n```\n\n**2. Make sure your embedding API is running**\n\n```bash\nollama pull embeddinggemma\nollama serve\n```\n\n**3. Point the server at your embedding API**\n\nOpen `docker-compose.yml` and set `EMBED_API_URL`.\n\n- Ollama runs on your host machine → use `http://host.docker.internal:11434/v1`\n  (works on macOS, Windows *and* Linux — the compose file maps\n  `host.docker.internal` to the host gateway for you).\n- Ollama runs somewhere else → use that address.\n\nWhile you\'re there, **change `MCP_API_KEY`** to your own secret.\n\n**4. Start everything**\n\n```bash\ndocker compose up --build\n```\n\nThe server is now live at **http://localhost:8000**.\n\n**5. Check it works**\n\n```bash\ncurl http://localhost:8000/mp/mcp/health\n```\n\n---\n\n## Connect an AI agent\n\nThe MCP endpoint is:\n\n```\nPOST http://localhost:8000/mp/mcp\nAuthorization: Bearer <your MCP_API_KEY>\n```\n\nPoint your MCP client (for example the [MemPalace](https://github.com/MemPalace/mempalace)\nclient) at this URL with your API key. See the main project for client setup.\n\n👉 For a full guide — client config, the protocol step by step, and every\navailable tool — see **[MCP_USAGE.md](MCP_USAGE.md)**.\n\n### Store and share documentation\n\nWant to load whole documents into the palace and let customers search them?\nThree ready-made Claude Code skills and a step-by-step guide live in\n[`skills/`](skills/):\n\n- [`mempalace-ingest-docs`](skills/mempalace-ingest-docs/SKILL.md) — file a document into MemPalace\n- [`mempalace-read-docs`](skills/mempalace-read-docs/SKILL.md) — search and export it\n- [`mempalace-zettelkasten`](skills/mempalace-zettelkasten/SKILL.md) — capture ideas as atomic, linked notes that resurface fast\n- [`skills/Beispiel.md`](skills/Beispiel.md) — full walkthrough, including a read-only key for customers\n\n#### Installing the skills\n\nThe skills work with [Claude Code](https://claude.com/claude-code) (and other\nclients that support the same skill format). Copy the ones you want into your\nskills folder:\n\n```bash\n# Per user (available in every project)\nmkdir -p ~/.claude/skills\ncp -r skills/mempalace-ingest-docs   ~/.claude/skills/\ncp -r skills/mempalace-read-docs     ~/.claude/skills/\ncp -r skills/mempalace-zettelkasten  ~/.claude/skills/\n```\n\nOr install them **per project** instead, so they ship with one repo:\n\n```bash\nmkdir -p .claude/skills\ncp -r /path/to/mempalace-server/skills/mempalace-ingest-docs   .claude/skills/\ncp -r /path/to/mempalace-server/skills/mempalace-read-docs     .claude/skills/\ncp -r /path/to/mempalace-server/skills/mempalace-zettelkasten  .claude/skills/\n```\n\nThen **restart Claude Code** (or run `/doctor` to reload). Each skill is a folder\nwith a `SKILL.md`; nothing else to build. The skills become available\nautomatically — just describe what you want (e.g. *"ingest docs/api.md into\nMemPalace"*), or invoke one directly with `/mempalace-ingest-docs`.\n\n> The skills call the MemPalace server, so connect it first (see\n> [MCP_USAGE.md](MCP_USAGE.md)) or enable the REST API. See\n> [`skills/Beispiel.md`](skills/Beispiel.md) for the end-to-end walkthrough.\n\n---\n\n## Access control: read vs write keys\n\nThe server supports two kinds of API key:\n\n| Key | Env variable | Can do |\n| --- | --- | --- |\n| **Full** | `MCP_API_KEY` | Everything — read **and** write |\n| **Read-only** | `MCP_API_KEY_READONLY` | Read only — search, list, get, … |\n\nThe read-only key is **optional**. Set it to give some clients (dashboards,\nread-only agents, monitoring) safe access that cannot change anything.\n\n- A read-only key may call non-mutating operations only. Any write — add,\n  update, delete, create tunnel, add/invalidate facts, change settings — is\n  rejected (`403` for REST, JSON-RPC error `-32003` for MCP).\n- The two keys **must be different**; the server refuses to start otherwise.\n- This applies to **both** the MCP endpoint and the optional REST API.\n\n```bash\n# Full access\nMCP_API_KEY="super-secret-write-key"\n# Optional read-only access\nMCP_API_KEY_READONLY="another-secret-read-key"\n```\n\n---\n\n## Optional: plain REST/JSON API\n\nMost users only need MCP. But if you want to talk to the palace from a normal\nscript, a `curl` command, or a non-MCP app, you can turn on a simple REST API.\n\nIt is **off by default**. Enable it with:\n\n```\nENABLE_REST_API=true\n```\n\nIt uses the **same `MCP_API_KEY`** for auth and lives under `/mp/api/v1`.\nIt is a thin wrapper over the same logic as MCP — same validation, same storage.\n\n| Method | Path | What it does |\n| --- | --- | --- |\n| `GET` | `/mp/api/v1/health` | Health check |\n| `GET` | `/mp/api/v1/status` | Palace overview (counts) |\n| `GET` | `/mp/api/v1/wings` | List wings |\n| `GET` | `/mp/api/v1/rooms?wing=` | List rooms |\n| `GET` | `/mp/api/v1/taxonomy` | Full wing → room tree |\n| `POST` | `/mp/api/v1/search` | Semantic search |\n| `GET` | `/mp/api/v1/drawers?wing=&room=&limit=&offset=` | List drawers |\n| `POST` | `/mp/api/v1/drawers` | Add a drawer |\n| `GET` | `/mp/api/v1/drawers/{id}` | Get one drawer |\n| `PATCH` | `/mp/api/v1/drawers/{id}` | Update a drawer |\n| `DELETE` | `/mp/api/v1/drawers/{id}` | Delete a drawer |\n\nExamples:\n\n```bash\nKEY="your-secret-key"\n\n# Search\ncurl -X POST http://localhost:8000/mp/api/v1/search \\\n  -H "Authorization: Bearer $KEY" \\\n  -H "Content-Type: application/json" \\\n  -d \'{"query": "what did we decide about auth?", "limit": 5}\'\n\n# Add a memory\ncurl -X POST http://localhost:8000/mp/api/v1/drawers \\\n  -H "Authorization: Bearer $KEY" \\\n  -H "Content-Type: application/json" \\\n  -d \'{"wing": "project-x", "room": "decisions", "content": "We use JWT auth."}\'\n\n# List memories\ncurl http://localhost:8000/mp/api/v1/drawers?wing=project-x \\\n  -H "Authorization: Bearer $KEY"\n```\n\n### Try it with Bruno\n\nA ready-to-use [Bruno](https://www.usebruno.com) collection for all REST\nendpoints is in the [`bruno/`](bruno/) folder. Bruno is a free, open-source\nAPI client (like Postman) that stores requests as plain files in your repo.\n\n1. Install Bruno, then **Open Collection** and pick the `bruno/` folder.\n2. Select the **Local** environment (top-right) and set your values:\n   - `baseUrl` — e.g. `http://localhost:8000`\n   - `apiKey` — your `MCP_API_KEY`\n   - `drawerId` — a real drawer ID (copy one from *Add Drawer* / *List Drawers*)\n3. Send any request. Bearer auth is applied automatically to all of them.\n\n---\n\n## Configuration\n\nAll settings come from environment variables.\n\n| Variable | What it does | Default |\n| --- | --- | --- |\n| `MEMPALACE_DB_URL` | PostgreSQL connection string (**required**) | – |\n| `MCP_API_KEY` | Full-access API key (read + write) | – |\n| `MCP_API_KEY_READONLY` | Optional read-only API key (see below) | empty |\n| `EMBED_API_URL` | OpenAI-compatible embedding API | `http://localhost:11434/v1` |\n| `EMBED_API_KEY` | API key for the embedding API (if needed) | empty |\n| `EMBED_MODEL` | Embedding model name | `embeddinggemma` |\n| `EMBED_DIM` | Embedding size — **must match the model** | `768` |\n| `MEMPALACE_TENANT_ID` | Keeps data separate per tenant | `default` |\n| `MEMPALACE_HNSW_EF_SEARCH` | Search quality (higher = better, slower) | `100` |\n| `ENABLE_REST_API` | Turn on the optional REST/JSON API (see below) | `false` |\n| `MEMPALACE_AGE_ENABLED` | Enable Apache AGE session setup and entity-graph tools | `false` |\n| `MEMPALACE_GRAPH_AUTO_POPULATE` | Auto-populate the AGE entity graph on `add_drawer` (see below) | `false` |\n| `MEMPALACE_GRAPH_EXTRACTOR` | Extraction strategy: `structural` or `llm` | `structural` |\n| `MEMPALACE_ROOM_REDIRECTS` | Enable room merge/rename redirects (see below) | `false` |\n| `LLM_PROVIDER` | Chat dialect for the `llm` extractor: `openai` or `ollama` (see below) | `openai` |\n| `LLM_API_URL` | Chat API base (only for `llm` extractor) — `openai`: incl. `/v1`; `ollama`: root without `/v1` | empty |\n| `LLM_API_KEY` | API key for the chat API (if needed) | empty |\n| `LLM_MODEL` | Chat model name (only for `llm` extractor) | empty |\n| `PORT` | Port the server listens on | `8000` |\n\n### Knowledge-graph auto-population\n\nBy default, `add_drawer` is **storage-only**: it stores the memory (vector +\nmetadata) and does **not** touch the Apache AGE entity graph. The graph is\npopulated only by explicit `kg_add_entity` / `kg_add_relation` calls. This is a\ndeliberate design choice — extraction is the client\'s job, which keeps the\nwrite path deterministic and free of LLM calls.\n\nApache AGE is disabled by default. On managed PostgreSQL services that do not\npermit application roles to run `LOAD \'age\'`, leave\n`MEMPALACE_AGE_ENABLED=false`; the plain-SQL temporal knowledge graph remains\navailable and no AGE session probe is attempted.\n\nIf AGE is installed and permitted, set `MEMPALACE_AGE_ENABLED=true`. To also\nfill the AGE graph automatically, set `MEMPALACE_GRAPH_AUTO_POPULATE=true` and\npick a strategy:\n\n- **`structural`** (default, no LLM) — deterministic. Every drawer becomes a\n  graph node linked to its room and wing:\n  `(Drawer) -[:IN_ROOM]-> (Room) -[:PART_OF]-> (Wing)`. These nodes carry the\n  `entity_type` `Drawer` / `Room` / `Wing`, so they stay distinguishable from\n  entities you add yourself. No network calls, no new dependencies.\n- **`llm`** — extracts real entities and relations from the drawer content via\n  a chat model. Set `LLM_API_URL`, `LLM_MODEL` (and `LLM_API_KEY` if required).\n  Closer to what MemPalace-family users may expect, at the cost of an LLM call in\n  the `add_drawer` write path. Pick the endpoint dialect with `LLM_PROVIDER`:\n    - **`openai`** (default) — OpenAI-compatible `/v1/chat/completions` (OpenAI,\n      LM Studio, LocalAI, Ollama\'s compat layer). Point `LLM_API_URL` at the base\n      **including** `/v1` (e.g. `http://host:11434/v1`). ⚠️ **Use a non-thinking\n      model here** — this endpoint cannot suppress a reasoning model\'s `<think>`\n      output, which streams for tens of seconds and exceeds the extraction\n      timeout, leaving the graph empty.\n    - **`ollama`** — Ollama-native `/api/chat` with `think=false`, which disables\n      reasoning so **thinking models (qwen3, …) work**. Point `LLM_API_URL` at the\n      Ollama root **without** `/v1` (e.g. `http://host:11434`).\n\nBoth require `MEMPALACE_AGE_ENABLED=true` and Apache AGE to be available. If\nauto-population is requested while AGE is disabled, it is automatically disabled\nand a startup log line explains why. Population is **best-effort** — if\nextraction fails, the drawer is still filed; the graph write is just skipped and\nlogged. Re-filing the same content is idempotent (graph MERGE), matching\n`add_drawer`\'s existing idempotency.\n\n### Room redirects\n\nOff by default. Set `MEMPALACE_ROOM_REDIRECTS=true` to merge or rename rooms\nwithout fragmenting the taxonomy: an old room forwards to a canonical one, its\ndrawers move with a pure metadata update (no re-embedding), and `add_drawer` /\n`mempalace_search` / `mempalace_list_drawers` transparently follow the redirect\nand echo where they landed. When the flag is off the feature is fully absent —\nthe redirect tools are not registered and drawer/search behavior is unchanged.\n\nSee **[ROOM_REDIRECTS.md](./ROOM_REDIRECTS.md)** for the tool list and a concrete\n`Auth → Authentication` merge walkthrough.\n\n### A note on `EMBED_DIM`\n\n`EMBED_DIM` must equal the embedding size your model actually returns — it\n**cannot be larger**. `embeddinggemma` returns **768** values. It also supports\nMatryoshka truncation *down* to **512 / 256 / 128** (smaller = faster and less\nstorage, with a small quality drop). For bigger vectors you need a different\nmodel (e.g. OpenAI `text-embedding-3-large` = 3072).\n\n---\n\n## Run from source (without Docker)\n\nYou need a PostgreSQL with the **pgvector** extension (and optionally\n**Apache AGE** for the entity graph).\n\n```bash\ncd server\n\nexport MEMPALACE_DB_URL="postgres://user:pass@localhost:5432/mempalace"\nexport MCP_API_KEY="your-secret-key"\nexport EMBED_API_URL="http://localhost:11434/v1"\nexport EMBED_MODEL="embeddinggemma"\nexport EMBED_DIM="768"\n\ngo run ./cmd/mempalace\n```\n\nThe server creates all the tables it needs on first start.\n\n### Project layout\n\nThe repo is a Go workspace (`go.work`) of three modules:\n\n- **`core/`** (`mempalace/core`) — shared library: storage, embedding client,\n  config, and the `consolidate` clustering logic.\n- **`server/`** (`mempalace/server`) — the MCP/HTTP server (imports `core`).\n- **`dreamjob/`** (`mempalace/dreamjob`) — the standalone room-consolidation job\n  (imports `core`), run as a Kubernetes CronJob. See\n  [ROOM_REDIRECTS.md](./ROOM_REDIRECTS.md).\n\nRun the dream job against the same database once:\n\n```bash\ncd dreamjob\nexport MEMPALACE_DB_URL="postgres://user:pass@localhost:5432/mempalace"\nexport EMBED_API_URL="http://localhost:11434/v1" EMBED_MODEL="embeddinggemma" EMBED_DIM="768"\ngo run .\n```\n\n---\n\n## Test environment (PostgreSQL + pgvector + AGE)\n\nTo run tests or try the entity-graph features, spin up an **isolated** database\nwith both extensions. It uses port **5433**, ephemeral `tmpfs` storage (clean on\nevery restart), and runs no app container — so it never touches your dev stack.\n\n```bash\n# Start (first run builds the AGE image; later runs are cached)\ndocker compose -f docker-compose.test.yml up -d --build\n\n# Connection string\npostgres://mempalace:mempalace_test@localhost:5433/mempalace_test\n\n# Stop and wipe\ndocker compose -f docker-compose.test.yml down\n```\n\nPoint the server at it and the entity graph (AGE) is provisioned automatically:\n\n```bash\ncd server\nMEMPALACE_DB_URL="postgres://mempalace:mempalace_test@localhost:5433/mempalace_test" \\\nMCP_API_KEY="test-key" PORT="8099" \\\nEMBED_API_URL="http://localhost:11434/v1" \\\ngo run ./cmd/mempalace\n# logs: "graph: kg_mp_default ready" → AGE is working\n```\n\nVerify the extensions directly:\n\n```bash\ndocker exec mempalace-test-testdb-1 psql -U mempalace -d mempalace_test \\\n  -c "SELECT extname, extversion FROM pg_extension WHERE extname IN (\'age\',\'vector\');"\n```\n\n---\n\n## Deploy to Kubernetes\n\nReady-to-use manifests are in the [`k8s/`](k8s/) folder (namespace, PostgreSQL\nStatefulSet, server Deployment, Service, Ingress, and Secret).\n\n```bash\nkubectl apply -f k8s/\n```\n\nEdit `k8s/secret.yaml` and `k8s/deployment.yaml` for your own database, API key,\nand embedding API before applying.\n\n### Try it locally on minikube\n\nWant to run the full stack on a local Kubernetes cluster first? A one-shot\nscript builds the images, creates the secret, and applies everything:\n\n```bash\n./k8s/minikube-setup.sh\n```\n\nSee **[k8s/MINIKUBE.md](k8s/MINIKUBE.md)** for the full guide.\n\n---\n\n## License\n\n[MIT](LICENSE)\n', 'docker-compose.yml': 'name: mempalace\n\n# ── Startup order ────────────────────────────────────────────────────────────\n# db (healthy) ─► app\n\nservices:\n\n  # --------------------------------------------------------------------------\n  # PostgreSQL 16 with pgvector + Apache AGE\n  # --------------------------------------------------------------------------\n  db:\n    build: ./k8s/postgres\n    # Pass shared_preload_libraries via command flag — most reliable across\n    # image versions. AGE requires it; pgvector does not.\n    command: ["postgres", "-c", "shared_preload_libraries=age"]\n    environment:\n      POSTGRES_DB:       mempalace\n      POSTGRES_USER:     mempalace\n      POSTGRES_PASSWORD: mempalace_local\n    volumes:\n      - pgdata:/var/lib/postgresql/data\n    healthcheck:\n      test: ["CMD-SHELL", "pg_isready -U mempalace -d mempalace"]\n      interval: 5s\n      timeout: 3s\n      retries: 12\n      start_period: 15s\n    restart: unless-stopped\n\n  # --------------------------------------------------------------------------\n  # MemPalace Go server\n  # --------------------------------------------------------------------------\n  app:\n    build:\n      context: .\n      dockerfile: server/Dockerfile\n    ports:\n      - "8000:8000"\n    # Make `host.docker.internal` resolve on native Linux Docker too (it is\n    # built in on macOS / Windows). Without this the default EMBED_API_URL\n    # below cannot reach an Ollama server running on the host.\n    extra_hosts:\n      - "host.docker.internal:host-gateway"\n    environment:\n      # Database\n      MEMPALACE_DB_URL:     "${MEMPALACE_DB_URL}"\n      # ⚠️  Change this key before exposing the port externally\n      # MCP_API_KEY grants full access (read + write).\n      #MCP_API_KEY:          "local-dev-key-change-me"\n      # Optional read-only key — its holders may only read, never mutate.\n      # Must differ from MCP_API_KEY. Leave empty to disable.\n      #MCP_API_KEY_READONLY: ""\n      # Embedding — external Ollama server\n      # embeddinggemma: multilingual (100+ languages), native 768 dims.\n      # EMBED_DIM must equal the model\'s output; cannot exceed it.\n      # embeddinggemma supports Matryoshka truncation DOWN to 512 / 256 / 128\n      # (smaller = faster & less storage, slightly lower quality). Not larger.\n      MCP_API_KEY:          "${MCP_API_KEY:-local-dev-key-change-me}"\n      MCP_API_KEY_READONLY: "${MCP_API_KEY_READONLY:-}"\n      ENABLE_REST_API:      "${ENABLE_REST_API:-true}"\n      MEMPALACE_TENANT_ID:  "${MEMPALACE_TENANT_ID:-default}"\n\n      EMBED_API_URL:        "${EMBED_API_URL:-http://host.docker.internal:11434/v1}"\n      EMBED_API_KEY:        "${EMBED_API_KEY:-}"\n      EMBED_MODEL:          "${EMBED_MODEL:-embeddinggemma}"\n      EMBED_DIM:            "${EMBED_DIM:-768}"\n      # Optional plain REST/JSON API at /mp/api/v1 (MCP is always on).\n      # Set to "true" to enable. Uses the same MCP_API_KEY for auth.\n      # ENABLE_REST_API:      "true"\n      # Multi-tenancy\n      # MEMPALACE_TENANT_ID:  "default"\n      # Tuning\n      MEMPALACE_HNSW_EF_SEARCH: "100"\n      MEMPALACE_PG_POOL_MIN:    "2"\n      MEMPALACE_PG_POOL_MAX:    "10"\n      # Apache AGE entity graph (opt-in, off by default). Leave false on\n      # managed PostgreSQL services that reject LOAD \'age\'.\n      # MEMPALACE_AGE_ENABLED: "true"\n      # Knowledge-graph auto-population (also requires AGE enabled).\n      # When "true", add_drawer also writes to the AGE entity graph.\n      # MEMPALACE_GRAPH_AUTO_POPULATE: "true"\n      # Strategy: "structural" (deterministic, no LLM — links\n      # drawer→room→wing) or "llm" (extracts entities/relations from content).\n      # MEMPALACE_GRAPH_EXTRACTOR: "structural"\n      # LLM extraction — only used when MEMPALACE_GRAPH_EXTRACTOR=llm.\n      # LLM_PROVIDER selects the endpoint dialect:\n      #   "openai" (default): /v1/chat/completions (Ollama compat, LM Studio,\n      #     OpenAI, …). LLM_API_URL must include /v1. NOTE: use a NON-thinking\n      #     model — reasoning output cannot be suppressed and blows the timeout.\n      #   "ollama": native /api/chat with think=false, so thinking models\n      #     (qwen3, …) work. LLM_API_URL must be the root WITHOUT /v1.\n      # LLM_PROVIDER: "ollama"\n      # LLM_API_URL: "http://host.docker.internal:11434"      # ollama: no /v1\n      # LLM_API_KEY: ""\n      # LLM_MODEL:   "qwen3"\n      # Room redirects (opt-in, off by default). When "true", exposes the\n      # redirect tools and makes add_drawer/search/list_drawers transparently\n      # follow a merged/renamed room to its canonical target. See ROOM_REDIRECTS.md.\n      # MEMPALACE_ROOM_REDIRECTS: "true"\n    depends_on:\n      db:\n        condition: service_healthy\n    restart: unless-stopped\n\n  # --------------------------------------------------------------------------\n  # "Dream" consolidation job — its own container, runs to completion.\n  # Not started by `docker compose up` (guarded by a profile). Run on demand:\n  #   docker compose run --rm dreamjob\n  # It scans rooms and writes near-duplicate merge PROPOSALS; review them via\n  # the MCP mempalace_list_merge_candidates tool. See ROOM_REDIRECTS.md.\n  # --------------------------------------------------------------------------\n  dreamjob:\n    build:\n      context: .\n      dockerfile: dreamjob/Dockerfile\n    profiles: ["dream"]           # only runs when explicitly invoked\n    extra_hosts:\n      - "host.docker.internal:host-gateway"\n    environment:\n      MEMPALACE_DB_URL:     "postgres://mempalace:mempalace_local@db:5432/mempalace"\n      MEMPALACE_TENANT_ID:  "default"\n      EMBED_API_URL:        "http://host.docker.internal:11434/v1"\n      EMBED_MODEL:          "embeddinggemma"\n      EMBED_DIM:            "768"\n      # Semantic tier (embedding similarity). Set "false" for exact-name only.\n      MEMPALACE_DREAM_SEMANTIC:  "true"\n      MEMPALACE_DREAM_THRESHOLD: "0.88"\n    depends_on:\n      db:\n        condition: service_healthy\n    restart: "no"                 # batch job — run once, don\'t restart\n\nvolumes:\n  pgdata:\n'}
GO_FILES = ["core/config/config.go", "core/storage/pool.go", "server/cmd/mempalace/main.go"]
def sha256_file(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()
def verify_contract(root: Path) -> None:
    config = (root / "core/config/config.go").read_text(encoding="utf-8")
    pool = (root / "core/storage/pool.go").read_text(encoding="utf-8")
    main_source = (root / "server/cmd/mempalace/main.go").read_text(encoding="utf-8")
    readme = (root / "README.md").read_text(encoding="utf-8")
    load_pos = pool.find('conn.Exec(ctx, "LOAD \'age\'")')
    gate_pos = pool.find("if !cfg.AGEEnabled")
    checks = [
        ("config exposes MEMPALACE_AGE_ENABLED default false", 'env:"MEMPALACE_AGE_ENABLED" envDefault:"false"' in config),
        ("pool gates AGE before LOAD", gate_pos >= 0 and load_pos >= 0 and gate_pos < load_pos),
        ("pgvector remains unconditional", pool.find("pgxvec.RegisterTypes") >= 0 and pool.find("pgxvec.RegisterTypes") < gate_pos),
        ("main gates AGE graph provisioning", "if cfg.AGEEnabled {" in main_source and "storage.ProvisionGraph" in main_source),
        ("main disables graph auto-population when AGE is off", "cfg.GraphAutoPopulate = false" in main_source),
        ("temporal triple-store availability is logged", "temporal triple-store KG remains available" in main_source),
        ("README documents MEMPALACE_AGE_ENABLED", "MEMPALACE_AGE_ENABLED" in readme),
    ]
    passed = 0
    for name, ok in checks:
        if not ok: raise RuntimeError(f"Contract diagnostic failed: {name}")
        passed += 1
        print(f"PASS: {name}")
    print()
    print(f"Summary: {passed} passed, 0 failed, {passed} total")
def main() -> int:
    root = Path.cwd().resolve()
    for required in ("go.work", "core/go.mod", "server/go.mod"):
        if not (root / required).exists(): raise RuntimeError(f"Run from mempalace-server repository root; missing {required}")
    for relative_path, baseline_hash in BASELINE_HASHES.items():
        target = root / relative_path
        if not target.is_file(): raise RuntimeError(f"Missing expected file: {relative_path}")
        current_hash = sha256_file(target)
        if current_hash not in {baseline_hash, FINAL_HASHES[relative_path]}:
            raise RuntimeError(f"Baseline mismatch for {relative_path}\nExpected original: {baseline_hash}\nExpected repeat-install: {FINAL_HASHES[relative_path]}\nActual: {current_hash}")
    backup_root = Path(tempfile.mkdtemp(prefix=".mempalace_age_gate_backup_", dir=root))
    backups = {}
    try:
        for relative_path in FILES:
            target = root / relative_path
            backup = backup_root / relative_path
            backup.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(target, backup)
            backups[relative_path] = backup
        for relative_path, content in FILES.items():
            target = root / relative_path
            temporary = target.with_name(f".{target.name}.{PATCH_ID}.{os.getpid()}.tmp")
            temporary.write_text(content, encoding="utf-8")
            os.replace(temporary, target)
        for relative_path, expected_hash in FINAL_HASHES.items():
            if sha256_file(root / relative_path) != expected_hash: raise RuntimeError(f"Post-write hash mismatch for {relative_path}")
        if shutil.which("gofmt"):
            for relative_path in GO_FILES:
                result = subprocess.run(["gofmt", "-d", relative_path], cwd=root, text=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
                if result.stdout: print(result.stdout, end="")
                if result.returncode != 0 or result.stdout: raise RuntimeError(f"gofmt validation failed for {relative_path}")
        else: print("WARNING: gofmt not found; source-format validation skipped.")
        verify_contract(root)
        print("Go compilation is deferred to the normal Railway build because this installer does not download toolchains.")
        print("MemPalace Apache AGE gate patch installed successfully.")
        print("Set Railway MEMPALACE_AGE_ENABLED=false")
        print("Set Railway MEMPALACE_GRAPH_AUTO_POPULATE=false")
        print("Redeploy only mempalace-server.")
        return 0
    except Exception:
        for relative_path, backup in backups.items(): shutil.copy2(backup, root / relative_path)
        raise
    finally: shutil.rmtree(backup_root, ignore_errors=True)
if __name__ == "__main__":
    try: raise SystemExit(main())
    except Exception as error:
        print(f"Installation failed: {error}", file=sys.stderr)
        raise SystemExit(1)
